13	    private static Item[] toItems(int[] values, int[] weights) {
14	        Item[] items = new Item[weights.length];
15	
16	        for (int itemIndex = 0; itemIndex < weights.length; itemIndex++) {
17	            items[itemIndex] = new Item(weights[itemIndex], values[itemIndex]);
18	        }
19	        return items;
