22	    private static final class Solver {
23	        private final CapacityTable capacityTable;
24	        private final Item[] items;
25	
26	        private Solver(int capacity, Item[] items) {
27	            capacityTable = new CapacityTable(capacity);
28	            this.items = items;
29	        }
30	
31	        private int solve() {
32	            for (Item item : items) {
33	                include(item);
34	            }
35	            return capacityTable.maxValueAt(capacityTable.capacity());
36	        }
37	
38	        private void include(Item item) {
39	            for (int currentCapacity = capacityTable.capacity(); item.fitsWithin(currentCapacity); currentCapacity--) {
40	                capacityTable.setMaxValueAt(
41	                        currentCapacity,
42	                        bestValueForCapacity(currentCapacity, item)
43	                );
44	            }
45	        }
46	
47	        private int bestValueForCapacity(int currentCapacity, Item item) {
48	            int valueWithoutItem = capacityTable.maxValueAt(currentCapacity);
49	            int valueWithItem = item.valueIfIncluded(capacityTable, currentCapacity);
50	            return Math.max(valueWithoutItem, valueWithItem);
51	        }
52	    }
53	
54	    private static final class CapacityTable {
55	        private final int[] maxValueByCapacity;
56	
57	        private CapacityTable(int capacity) {
58	            maxValueByCapacity = new int[capacity + 1];
59	        }
60	
61	        private int capacity() {
62	            return maxValueByCapacity.length - 1;
63	        }
64	
65	        private int maxValueAt(int capacity) {
66	            return maxValueByCapacity[capacity];
67	        }
68	
69	        private void setMaxValueAt(int capacity, int value) {
70	            maxValueByCapacity[capacity] = value;
71	        }
72	    }
